export function SampleTaierzhuangDem(x, z) {
  const m = TAIZHUANG_HEIGHTMAP;
  const u = Math.max(0, Math.min(1, (x - m.worldBounds.minX) / (m.worldBounds.maxX - m.worldBounds.minX)));
  const v = Math.max(0, Math.min(1, (z - m.worldBounds.minZ) / (m.worldBounds.maxZ - m.worldBounds.minZ)));
  const px = u * (m.width - 1), pz = v * (m.height - 1);
  const x0 = Math.floor(px), z0 = Math.floor(pz);
  const x1 = Math.min(m.width - 1, x0 + 1), z1 = Math.min(m.height - 1, z0 + 1);
  const tx = px - x0, tz = pz - z0;
  const north = TAIZHUANG_HEIGHTS_DM[z0 * m.width + x0] * (1 - tx)
    + TAIZHUANG_HEIGHTS_DM[z0 * m.width + x1] * tx;
  const south = TAIZHUANG_HEIGHTS_DM[z1 * m.width + x0] * (1 - tx)
    + TAIZHUANG_HEIGHTS_DM[z1 * m.width + x1] * tx;
  return (north * (1 - tz) + south * tz) / 10;
}
